"use client"

import animation from "react-useanimations/lib/folder"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Folder" from https://useanimations.com (MIT): https://useanimations.com/icons/folder
export function AnimatedFolder(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover"
      {...props}
    />
  )
}
